pub fn next_delay(attempt: u32, config: &RetryConfig) -> u64 {
    let exponent = attempt.saturating_sub(1);
    let raw = if config.base_delay_ms == 0 {
        0
    } else if exponent >= 64 {
        u64::MAX
    } else {
        config
            .base_delay_ms
            .checked_mul(1u64 << exponent)
            .unwrap_or(u64::MAX)
    };
    raw.min(config.max_delay_ms)
}

